const PEOPLE_DATA = [{"id": "borozna", "name": "Борозна (Шевченко) Любовь Яковлевна", "short_name": "Борозна Любовь Яковлевна", "birth_date": "25 ноября 1925 г.", "birth_place": "деревня Селище, Светлогорский р-н, Гомельская обл.", "deportation_age": "17 лет (июнь 1943 г.)", "destination": "Германия (западнее Берлина, станция Хойер, частное хозяйство бауэра)", "liberation": "Май 1945 г., американские войска на Эльбе, переданы советскому командованию", "quote": "«И в рабочие дни и в будни утром рано раздавался голос хозяйки: „Ljuba, steh auf!“. От тяжелой работы порой тошнило... Нас считали низшей расой».", "avatar": "images/photo_02_borozna_1948.jpg", "photos": [{"src": "images/photo_01_borozna_1953.jpg", "caption": "Фото 1. Борозна Л.Я., 1953 год, начало трудовой деятельности Давыд-Городок", "tag": "Фото 1 • 1953 г."}, {"src": "images/photo_02_borozna_1948.jpg", "caption": "Фото 2. Борозна Л.Я., 1948 год, учеба в училище (в центре с подругами)", "tag": "Фото 2 • 1948 г."}], "story": {"family": "Отец — Шевченко Яков Иванович, работал в колхозе; мама — Шевченко Мария Герасимовна, вела домашнее хозяйство. Семья была многодетной: старшая Дарья (учительница), Евфросиния (колхозница), братья Яков, Миша, Саша и Любовь.", "war_start": "О начале войны узнали внезапно: у них гостил родственник майор Прохор Кондратенко, когда прилетел немецкий самолет и сбросил бомбу рядом с деревней. Майор поспешил в часть в Витебск. В 1941–1942 гг. в деревне была тишина, но в 1942 г. в Шатилках разместились оккупанты. Днем они грабили сараи, а ночью приходили партизаны.", "deportation": "В 1943 г. при отступлении немцы начали жечь деревни. На праздник Троицы каратели пришли в Селище. Старшие сестры спрятались, а Любовь с матерью заставили жарить драники немцам. К вечеру жителей погнали под конвоем, постройки сожгли дотла. Семья ушла в чем стояла. Гнали через Чернейку, Красное, Речицу, погрузили в эшелон и привезли в Брест. Там людей отсортировали: трудоспособных отделили от матерей с малыми детьми. Через Ровно и дезинфекцию эшелон доставил их в Германию западнее Берлина. Пассажиры-немцы в электричках плакали, видя босых белорусских детей.", "forced_labor": "В Хойере семью отобрал бауэр, но полицай перенаправил Любовь к другим хозяевам. С июня 1943 г. по май 1945 г. Любовь жила отдельно от родителей и братьев. В хозяйстве было 6 коров, свиньи, куры. Приходилось доить, вязать снопы, грузить, молотить. За малейший недодой хозяйка жестоко ругала. Спала в неотапливаемой комнатке с цементным полом. Рядом размещались 10 французских военнопленных. Любовь неоднократно пыталась сбежать к родителям, но полиция возвращала её назад.", "liberation": "Весной 1945 г. американские войска вошли в деревню и приказали прекратить работу. Предлагали уехать в США, но семья стремилась только на Родину. Американцы доставили семью к реке Эльбе, переправили на советскую сторону, откуда военные отправили их в Беларусь.", "peace_life": "По возвращении жили в землянке, строили деревянный дом, спасали чудом уцелевшую корову. Любовь окончила 5-й класс, затем училище по специальности «агроном», техникум и заочно Институт механизации сельского хозяйства. Работала экономистом. В 1955 г. вышла замуж за Борозну Владимира Ивановича, вырастили троих сыновей: Олега, Юрия и Сергея."}}, {"id": "bugaev", "name": "Бугаёв Евгений Леонтьевич", "short_name": "Бугаёв Евгений Леонтьевич", "birth_date": "06 июня 1937 г.", "birth_place": "окраина г. Микашевичи (сожжена в ноябре 1942 г.)", "deportation_age": "6 лет (август 1943 г.)", "destination": "Концлагерь Майданек (Польша) → поместье Альт-Бисдорф (Берлин, станция Кёпеник)", "liberation": "23 апреля 1945 г. советскими войсками при штурме Берлина", "quote": "«Грустно осознавать себя рабами, а нам обещалось пожизненное рабство: работают родители, а их дети подрастают потенциальными, покорными рабами... Немцы брали рабов на перспективу».", "avatar": "images/photo_03_bugaev_2013.jpg", "photos": [{"src": "images/photo_03_bugaev_2013.jpg", "caption": "Фото 3. Бугаев Е.Л., 10.02.2013 год, средняя школа №2", "tag": "Подлинный портрет"}, {"src": "images/photo_04_bugaev_cert_2005.jpg", "caption": "Фото 4. Удостоверение «Узника нацизма», выданное Бугаеву Е.Л., 2005 г.", "tag": "Архивный документ"}], "story": {"family": "Мама, Кучаева Ольга Петровна, вела домашнее хозяйство; отец, Леонтий Николаевич, трудился на лесозаводе. В семье росли братья Коля и Саша. Жили на окраине Микашевичей на Рудне.", "war_start": "В ноябре 1942 г. подпольщик Иван Конопацкий взорвал кинотеатр с фашистами. Каратели сожгли дом Бугаёвых. Семья перебралась на хутор возле деревни Запросье к тете Варваре. Там держали тайную связь с партизанами, снабжали их продуктами.", "deportation": "В конце июля 1943 г. партизаны предупредили об опасности, но семью выдал предатель. На рассвете всех арестовали, увезли в тюрьму Пинска, а после Курской битвы отправили в концлагерь Майданек (Люблин, Польша). В памяти 6-летнего мальчика навсегда остались длинные деревянные бараки, нары и удушливый запах крематория. Через две недели узников выстроили на продажу в рабство. Немецкий управляющий ощупывал рослого отца, после чего семью Бугаёвых и Ковальских увезли в поместье Альт-Бисдорф под Берлином.", "forced_labor": "Жили в комнатке 3х4 метра с двухъярусными нарами и угольной печуркой. Кормили эрзац-хлебом наполовину с опилками и баландой. Французские военнопленные тайком подкармливали детей сушеной сахарной свеклой — «вкуснее шоколадных конфет». Внуки помещика называли советских детей «russische Schweine» и избивали 6-летнего Женю в живот. Однажды дедушка-помещик избил мальчика до крови за сорванный виноград. В 1944–1945 гг. Берлин бомбили каждую ночь; младший братик Максим заболел воспалением легких и умер в бомбоубежище винного завода. Отец с товарищем прятали на территории завода сбитого советского летчика.", "liberation": "16 апреля 1945 г. началась битва за Берлин, линия фронта прошла прямо по пригородному поместью. 23 апреля 1945 г. семью освободили бойцы Красной Армии. Отца за знание немецкого языка зачислили в армейский особый отдел для выявления скрывавшихся нацистов. В июле 1945 г. семья вернулась в Брест.", "peace_life": "Вернулись на пепелище, жили у родственников Скрипалей, в 1948 г. отстроили дом. Евгений Леонтьевич получил образование, стал главным инженером автобазы №10 г. Лунинца. В 1959 г. женился на медсестре Марии Михайловне, воспитали дочерей Наталью (архитектор) и Лилию (врач). В 1970 г. посетил мемориал Майданек, где пережил глубокое потрясение от оживших воспоминаний."}}, {"id": "buguk", "name": "Бугук Фёдор Семёнович", "short_name": "Бугук Фёдор Семёнович", "birth_date": "23 февраля 1925 г.", "birth_place": "д. Мокрово, Ленинский р-н, Пинская обл.", "deportation_age": "17 лет (май 1942 г.)", "destination": "Трудовой лагерь Мариензиль (Вильгельмсхафен, Германия), заводы подводного флота", "liberation": "Май 1945 г., канадские войска, передан советскому командованию", "quote": "«Годы службы в армии — это лучшие годы моей жизни (1945–1950 гг.), а три предыдущих года (1942–1945 гг.) — мытарства раба невольного».", "avatar": "images/photo_05_buguk_1940.jpg", "photos": [{"src": "images/photo_05_buguk_1940.jpg", "caption": "Фото 5. Федор (слева) с другом Андреев 1940 год, Лунинецкое училище", "tag": "Оригинальный снимок"}, {"src": "images/photo_06_mariensiel_women_1943.jpg", "caption": "Фото 6. Трудовой лагерь Мариензиль, 1943 год", "tag": "Лагерный архив"}, {"src": "images/photo_07_buguk_1947.jpg", "caption": "Фото 7. Федор (стоит) с другом, 1947 год", "tag": "Советская Армия"}], "story": {"family": "В семье росло девятеро детей. Мама — Прасковья Петровна, отец — Семён Максимович, крестьяне. Жили на хуторе. До 1939 г. Фёдор учился в польской школе, в 1940 г. поступил в железнодорожное училище в Лунинце на помощника машиниста.", "war_start": "В июне 1941 г. директор училища отпустил курсантов по домам. Фёдор вернулся на хутор. В 1942 г. начался принудительный угон молодежи. Фёдора арестовали в Лунинце, но отцу удалось вызволить сына. Юноша скрывался в лесу, но 1 мая 1942 г. зашел переночевать домой и был схвачен карателями.", "deportation": "Через КПЗ в Лунинце и казармы в Бресте в товарных вагонах с колючей проволокой Фёдора отправили в Германию. Попал в лагерь Мариензиль в городе Вильгельмсхафен. Распределили на машиностроительный завод «Maschinenbaubetrieb». Заметив нечеловеческие условия у станков, Фёдор по совету старших рабочих специально запорол деталь, после чего его перевели на разгрузку кокса, брюквы и картофеля.", "forced_labor": "Попытался заступиться за избиваемого немецким надзирателем рабочего — угодил в карцер и тюрьму на три недели. Затем направлен на приборостроительный завод в цех «Купершмидт», где выпускали узлы для подводных лодок. За подозрение в краже брюквы из столовой был зверски избит гестаповцами резиновыми дубинками до потери сознания. Сидел в переполненной камере гестапо с полешуками Губичем и парнем по кличке «Готель».", "liberation": "В конце войны узников вывели в поле под пулеметы охраны, но утром охрана сбежала. В лагерь прибыли канадские солдаты на машинах с кленовыми листьями, раздававшие галеты. Вскоре подошли советские части и переправили узников через Эльбу.", "peace_life": "Фёдор добровольно вступил в ряды Красной Армии: служил в батальоне особого назначения, затем в 350-м гаубичном полку в Эленбурге мастером по вооружению, дослужился до старшины полка. Демобилизовался в 1950 г. Работал машинистом и слесарем на лесозаводе и мельнице в Микашевичах. Женился на Любови, после ее смерти — на ее сестре Вере Леонтьевне. Вырастил четверых детей."}}, {"id": "vysotskaya", "name": "Высоцкая Вера Ивановна", "short_name": "Высоцкая Вера Ивановна", "birth_date": "03 января 1928 г.", "birth_place": "д. Западная Морочь, Солигорский р-н, Минская обл.", "deportation_age": "14 лет (1942 г.)", "destination": "Германия (область Люкенвальд, район Интербок, сельсовет Клюскотива, д. Шильновайда)", "liberation": "Весна 1945 г., советские войска", "quote": "«Хозяин Рихард имел 5 коров... Я надаивала по четыре бака молока. Мне было четырнадцать лет, когда фашисты увезли в Германию. Работать было очень трудно».", "avatar": "images/photo_09_vysotskaya_cert_1992.jpg", "photos": [{"src": "images/photo_09_vysotskaya_cert_1992.jpg", "caption": "Фото 9. Удостоверение №587926, узнику концлагеря Высоцкой Вере Ивановне", "tag": "Архивный оригинал"}], "story": {"family": "Родилась и выросла в крестьянской семье в деревне Западная Морочь на Солигорщине. С малых лет приучена к крестьянскому труду.", "war_start": "В 1941 г. родные места оказались в зоне жестокой оккупации. Окрестные леса кишели карательными отрядами, боровшимися с партизанами.", "deportation": "В 1942 г. в 14-летнем возрасте во время облавы схвачена фашистами и угнана в эшелоне на принудительные работы в Германию.", "forced_labor": "Попала к немецкому фермеру Рихарду в деревню Шильновайда (округ Люкенвальд, район Интербок). Будучи подростком, выполняла непосильную норму: обслуживала коровник, вручную надаивала ежедневно по четыре бака молока, выполняла тяжелые полевые работы.", "liberation": "Освобождена весной 1945 г. частями Советской Армии, вернулась на разрушенную войной белорусскую землю.", "peace_life": "Проживала в Лунинецком районе, добросовестно трудилась на восстановлении народного хозяйства. 3 ноября 1992 г. Лунинецким райсобесом ей было выдано бессрочное государственное удостоверение бывшего узника фашистских лагерей."}}, {"id": "konopatskaya", "name": "Конопацкая (Кулакевич) Лидия Борисовна", "short_name": "Конопацкая Лидия Борисовна", "birth_date": "07 февраля 1930 г.", "birth_place": "посёлок Микашевичи, Ленинский р-н, Пинская обл.", "deportation_age": "12 лет (ноябрь 1942 г.)", "destination": "Центр Берлина (лагерь у Бранденбургских ворот, гостиница и ресторан фрау Пэрстки)", "liberation": "04 мая 1945 г. советскими воинами", "quote": "«Маме моей сообщили, что меня расстреляли... В лагере в центре Берлина виднелись Бранденбургские ворота. Сильно бомбили город. Отнято было детство и старость тяжёлая... Война осталась с постоянным чувством голода».", "avatar": "images/photo_10_konopatskaya_2013.jpg", "photos": [{"src": "images/photo_10_konopatskaya_2013.jpg", "caption": "Фото 10. Конопацкая Л. Б., 21.04.2013 год", "tag": "Подлинный портрет"}, {"src": "images/photo_11_kulakevich_archive_1991.jpg", "caption": "Фото 11. Архивная справка Кулакевич Лилии Борисовне (Госархив Брестской области в г. Пинске)", "tag": "Архивная справка"}, {"src": "images/photo_12_konopatskaya_cert_1991.jpg", "caption": "Фото 12. Удостоверение узника нацизма № 589885 Конопацкой Лидии Борисовне", "tag": "Удостоверение"}, {"src": "images/photo_13_konopatskaya_vkladysh.jpg", "caption": "Фото 13. Вкладыш удостоверения несовершеннолетнего узника нацизма", "tag": "Вкладыш к льготам"}], "story": {"family": "Отец, Борис Павлович Кулак, умер от тяжелой болезни в 1942 г. Мама, Ольга Прокоповна, осталась с семью детьми: Елена, Ева, Константин, Евдокия, Иван, Иосиф, Лидия и Владимир. Православная верующая семья.", "war_start": "В 1942 г. нацисты сожгли южную часть Микашевичей. После уничтожения еврейского населения семью Кулакевич переселили в пустующий дом на Болотной улице, где дети спали на полу. Старший брат Костя держал связь с партизанами.", "deportation": "В ноябре 1942 г. фашисты оцепили Микашевичи. Мать с детьми ушла в лес, но 12-летняя Лида с подругой Олей ночевали у старшей сестры на ул. 17 Сентября. Утром девочек схватили. Местный солтус Лисовский предлагал Лиде удочерение ради спасения, но девочка надеялась, что её отпустят. В Лунинце группу людей вывезли к расстрельной яме — расстрел в последний момент отменила русская переводчица, уговорившая офицера отправить людей в рабство. Маме сообщили, что Лиду расстреляли.", "forced_labor": "Через тюрьму Пинска и товарные вагоны Лиду доставили в центр Берлина в лагерь у Бранденбургских ворот. Узники обслуживали ресторан и отель фрау Пэрстки. Носили нашивки «OST». Лифтёрша ресторана тайком прятала для 12-летней Лиды объедки, спасая от голодной смерти. При бомбежках Берлина обрушивались этажи, Лида расчищала битый кирпич и красила стены.", "liberation": "Три недели в апреле 1945 г. прятались в бункере у реки Шпрее без еды между линиями фронта. 4 мая 1945 г. освобождены советскими бойцами. Лидию зачислили в армейский прачечный отряд на Эльбе, где она проработала полгода. В ноябре 1945 г. после проверки вернулась в Микашевичи — мать от потрясения не сразу узнала повзрослевшую дочь.", "peace_life": "Окончила вечернюю школу, трудилась счетоводом поссовета (10 лет), статистиком в сельпо (15 лет) и 10 лет на железной дороге. В 1952 г. вышла замуж за Конопацкого Владимира Игнатьевича, родила троих детей (Валентина, Михаил, Тамара)."}}, {"id": "koshel", "name": "Кошель (Флорьянович) Елена Михайловна", "short_name": "Кошель Елена Михайловна", "birth_date": "10 июня 1925 г.", "birth_place": "д. Семигостичи, Столинский р-н, Брестская обл.", "deportation_age": "18 лет (1943 г.)", "destination": "Германия (г. Штендель, деревня Унглинген, бауэр Реклем)", "liberation": "1945 г. американскими войсками, переданы советским солдатам", "quote": "«Овощи воровали и для русских парней, работавших на аэродроме в километре от деревни Унглинген. Мы зарывали в ямку картофель и свеклу, обозначали веточкой. Парни приходили ночью и уносили припрятанное. Так мы спасали их от голода».", "avatar": "images/photo_14_koshel_2013.jpg", "photos": [{"src": "images/photo_14_koshel_2013.jpg", "caption": "Фото 14. Кошель Елена Михайловна, 05.05.2013 год", "tag": "Подлинный портрет"}], "story": {"family": "Отец, Флорьянович Михаил Иосифович, работал в местном самоуправлении; мать — Елизавета Юстиновна. В большой семье воспитывалось девятеро детей: Надежда, Наталья, Валентина, Александр, Иосиф, Николай, Елена, Степан, Свирид.", "war_start": "До войны жили дружно, с восьми лет девочки пряли и ткали лен. Летом 1941 г. деревню оккупировали захватчики.", "deportation": "В 1943 г. каратели забрали из дома сразу троих: Валентину, Елену и Николая. Николая отпустили в деревне, а сестер через лагерь в Столине и открытый эшелон без удобств доставили в Магдебург, затем в Штендель. Крупный помещик Реклем отобрал четырех девушек («vier Mädchen») из одной деревни Семигостичи и увез на телеге в село Унглинген.", "forced_labor": "Трудились на сельхозработах с 6:30 утра до 19:00 вечера без выходных, кроме воскресенья. Паек — булка хлеба и маргарин на неделю. В поле девушки тайком прятали овощи и отмечали тайники палочками, чтобы голодающие советские военнопленные с аэродрома могли забрать еду ночью под угрозой виселицы.", "liberation": "В 1945 г. пережили налеты союзной авиации в бомбоубежищах. Освобождены американскими войсками, переправлены через Эльбу в советскую зону и эшелоном вернулись домой.", "peace_life": "Вернулась в родительский дом. В Семигостичах встретила мужа — тоже вернувшегося из неволи остарбайтера. Всю жизнь добросовестно трудилась в колхозе доглядчицей свиней и телят. Воспитали троих детей (Валентина — медсестра, Мария — воспитатель, Владимир — строитель)."}}, {"id": "krukovskaya", "name": "Круковская (Кулакевич) Анна Григорьевна", "short_name": "Круковская Анна Григорьевна", "birth_date": "29 июля 1929 г.", "birth_place": "местечко Вильча, Житковичский р-н, Гомельская обл.", "deportation_age": "13 лет (февраль 1943 г.)", "destination": "Германия (Виттенберг – Пудлец, д. Загост бай Пудлец, бауэр Вильям Вегнер)", "liberation": "03 мая 1945 г. советскими воинами", "quote": "«Повторялось слово лёйзе (die Läuse — вши). Уверена, другие, как и я, ощущали себя вещами, которые покупают на распродаже. Я была самой маленькой, и брать меня никто не хотел...»", "avatar": "images/photo_15_krukovskaya_2013.jpg", "photos": [{"src": "images/photo_15_krukovskaya_2013.jpg", "caption": "Фото 15. Круковская А.Г. с мужем, 2013 год", "tag": "Оригинальный снимок"}, {"src": "images/photo_16_krukovskaya_cert_1994.jpg", "caption": "Фото 16. Удостоверение несовершеннолетнего узника № 066106, Круковской А.Г.", "tag": "Удостоверение"}], "story": {"family": "В три года потеряла мать, воспитывалась у бабушки в деревне Юркевичи, затем жила у тети Наташи в селе Ленино.", "war_start": "17 февраля 1943 г. каратели устроили расправу над деревней Ленино. Тетю Наташу вместе с односельчанами сожгли заживо в кузнице и расстреляли. 13-летней Ане фашист крикнул «Halt!» и приказал гнать стадо коров в Микашевичи.", "deportation": "Ночевала в ящике из-под спичек в хозмаге. Товарняком отправлена через Барановичи и Белосток в Германию. В Виттенберге покупатели ходили по кругу, тыкая в детей тростью. 13-летнюю худенькую девочку последним забрал бауэр Вильям Вегнер в деревню Загост бай Пудлец.", "forced_labor": "Подъем в 4 утра: дойка 6 коров, варка котла картофеля, уход за свиньями, лошадьми, птицей. Два года вручную очищала гигантское поле от тяжелых неподъемных камней. Носила нашивку «OST», терпела насмешки и угрозы отправки в концлагерь.", "liberation": "3 мая 1945 г. в село вошли первые советские солдаты. Но путь домой лежал через военные прачечные в Пудлеце и Яворе: девочки наждачной бумагой вручную отстирывали окровавленное простреленное обмундирование бойцов. В августе 1946 г. в телячьем вагоне на цепях с коровами прибыла в Гродно, а 16 августа — в Микашевичи.", "peace_life": "С 1948 г. боролась с малярией в санстанции. В 1953 г. вышла замуж за железнодорожника Круковского Николая Трофимовича. Прожили душа в душу более 60 лет, воспитали сыновей Анатолия и Михаила, дождались правнуков."}}, {"id": "kuntsevich", "name": "Кунцевич (Михновец) Любовь Ивановна", "short_name": "Кунцевич Любовь Ивановна", "birth_date": "11 июня 1923 г.", "birth_place": "деревня Морочь, Солигорский р-н, Минская обл.", "deportation_age": "19 лет (февраль 1943 г.)", "destination": "Германия (Потсдам, тюрьма → поместье Брунов в 20 км от Лейпцига)", "liberation": "Апрель 1945 г. советскими солдатами", "quote": "«Самое трудное воспоминание — как убивали родных. Меня вели, а я смотрела на убитую маму. И сейчас отчётливо помнится, как она лежала в тёплом платке в клетку — такие платки называли «опинянкой»...»", "avatar": "images/photo_17_kuntsevich_2013.jpg", "photos": [{"src": "images/photo_17_kuntsevich_2013.jpg", "caption": "Фото 17. Кунцевич Л.И., 2013 год", "tag": "Подлинный портрет"}, {"src": "images/photo_18_kuntsevich_unit_1945.jpg", "caption": "Фото 18. 1945 год, военная часть", "tag": "Победный 1945 год"}, {"src": "images/photo_19_kuntsevich_return_1945.jpg", "caption": "Фото 19. Кунцевич Л.И., после возвращения 1945 год, Морочь", "tag": "Оригинальный снимок"}], "story": {"family": "Родители, Иван Евсеевич и Евдокия Фёдоровна, работали в колхозе. В семье росли четверо детей: Владимир, Михаил, Елена и Любовь.", "war_start": "В феврале 1943 г. вся семья находилась в партизанах. Каратели окружили и разгромили отряд. Отца, мать и двоих братьев расстреляли на глазах Любови. Сестер Елену и Любовь пощадили ради рабского труда.", "deportation": "Через Старобин девушек привезли в тюрьму Потсдама: каменный мешок без еды. Через несколько дней сестер отобрал хозяин поместья Брунов (20 км от Лейпцига).", "forced_labor": "Тяжелый полевой труд с 7 утра до сумерек. Буханка хлеба и брюква на неделю. За попытки достать мерзлую картошку в поле жестоко избивали палками. Сестры предприняли побег, но были пойманы полицией, брошены в карцер и проданы другому помещику.", "liberation": "В апреле 1945 г. освобождены советскими солдатами. До ноября 1945 г. работали на военном заводе и кухне армейской части.", "peace_life": "Вернулась в родную деревню Морочь — кругом одно пепелище. Жила в землянке. Переехала в Микашевичи, работала в ткацком цеху, плела корзины. Вышла замуж за Кунцевича Николая Владимировича, воспитала сына Геннадия и дочь Антонину, имеет четверых внуков."}}, {"id": "polessa", "name": "Полесса Кристина Чеславовна", "short_name": "Полесса Кристина Чеславовна", "birth_date": "02 апреля 1938 г.", "birth_place": "местечко Микашевичи, Лунинецкий р-н, Пинская обл.", "deportation_age": "6 лет (1944 г.)", "destination": "Германия (лагерь Фленсбург на границе с Данией)", "liberation": "1945 г. американскими войсками, возвращение в 1946 г.", "quote": "«Меня постоянно преследовало чувство голода, но взять нельзя было ничего. У меня была мечта: когда я стану взрослой и начну работать, я куплю себе целый мешок конфет!»", "avatar": "images/photo_20_polessa_2013.jpg", "photos": [{"src": "images/photo_20_polessa_2013.jpg", "caption": "Фото 20. Полесса К.Ч. , 2013 год, средняя школа №2", "tag": "Подлинный портрет"}, {"src": "images/photo_21_polessa_poland_1946.jpg", "caption": "Фото 21. 16.05.1946 год, Польша, г.Пшасныш", "tag": "Детство 1946 г."}, {"src": "images/photo_22_polessa_grad_1952.jpg", "caption": "Фото 22. Кристина Чеславовна с подругой, после окончания 7 класса", "tag": "Оригинальный снимок"}], "story": {"family": "Единственная дочь в семье. Отец, Полесса Чеслав Болеславович, слесарь фанерного завода, погиб в 1939 г. на польско-германском фронте. Мама — Валентина Игнатьевна. Семья католического вероисповедания.", "war_start": "Жили на Фабричной улице (микрорайон Рудня). В ноябре 1942 г. чудом избежали гибели при угрозе сожжения поселка.", "deportation": "В 1944 г. при отступлении немцев автоматчики оцепили барак. Всю семью (дедушку, бабушку, тетю, маму и 6-летнюю Кристину) в скотских вагонах увезли в Фленсбург на границу с Данией.", "forced_labor": "Лагерный барак, нары, колючая проволока. Дети пролезали под проволокой на шоссе. Мама и тетя убирали туалеты на железной дороге в 5 км от барака. За зеленую брюкву грозил расстрел. Семья немецких детей по соседству тайком подарила девочке фартук и сфотографировала на память.", "liberation": "Освобождены американцами. Попали в польский город Пшасныш при советской летной части, где дедушка работал истопником. В 1946 г. семья вернулась в Бобруйск, затем в Микашевичи.", "peace_life": "Кристина выучила русский язык, пела в хоре. Окончила Гомельское музыкальное училище и Ленинградский институт культуры им. Н.К. Крупской по специальности «хоровое дирижирование». 39 лет преподавала хоровые дисциплины в Гродненском музпедучилище, награждена медалью «Ветеран труда». Сыновья — Виталий (врач) и Владислав (педагог, художник)."}}, {"id": "saley", "name": "Салей (Гешавец) Елена Германовна", "short_name": "Салей Елена Германовна", "birth_date": "03 апреля 1932 г. (92 года)", "birth_place": "местечко Микашевичи, Ленинский р-н, Пинская обл.", "deportation_age": "9–10 лет (1942 г.)", "destination": "Германия (пригород Гамбурга, крупное поместье бауэра)", "liberation": "Май 1945 г. английскими войсками", "quote": "«В распределительном пункте хозяин выбрал только мать, а девочек должны были отправить в концлагерь. Но мать твердо сказала: „Или всех вместе, или я не пойду работать к вам!“. Бауэр вынужден был согласиться...»", "avatar": "images/photo_23_saley_family_1957.jpg", "photos": [{"src": "images/photo_23_saley_family_1957.jpg", "caption": "Фото 23 / Фото 1. Иосиф и Елена с сыновьями Виктором и Леонидом, 1957 г.", "tag": "Семья Салей 1957 г."}, {"src": "images/photo_24_saley_kgb_1995.jpg", "caption": "Фото 24. Архивная справка управления комитета госбезопасности семье Салей, Гешавец, Карпинской (сестрам Елены)", "tag": "Справка УКГБ РБ"}], "story": {"family": "Родилась в большой семье Германа и Ольги Гешавец (11 детей, 7 умерли маленькими, выжили 4 дочери: Ольга, Наталья, Елена и Мария). Отец умер в 1934 г. Мать одна тянула хозяйство.", "war_start": "Летом 1941 г. во время сбора черники в лесу девочки услышали разрыв первых бомб у железной дороги. В ноябре 1942 г. после взрыва кинотеатра Конопацким спасались в партизанском отряде, жили в шалаше, варили крапиву. При попытке вернуться были схвачены.", "deportation": "В 1942 г. погружены в товарный эшелон. В распределителе бауэр хотел забрать только взрослую мать, а дочерей отправить в концлагерь смерти. Мужество матери Ольги Ефимовны спасло детей: она поставила ультиматум и добилась, чтобы детей взяли вместе с ней в поместье под Гамбургом.", "forced_labor": "Поселили в холодной кладовой, спали на соломенной перине. Хозяйка кричала на 9-летнюю Лену даже за упавшее яблоко. Младшая Маша собирала яйца птицы, старшие пололи, сеяли и жали. Ходили в деревянных колодках. Лена научилась ездить на велосипеде и развозила записки и поручения хозяина.", "liberation": "В мае 1945 г. семью освободили британские войска. Вернулись на пепелище родных Микашевичей — дом был полностью разрушен.", "peace_life": "Елена окончила 4 класса и вечернюю школу, работала няней, затем на Лесозаводе. Вышла замуж за Иосифа Салея (1931 г.р.). Вырастили троих сыновей: Леонида (работал на РУПП «Гранит»), Виктора и Владимира. Правнучка Софья Салей бережно сохранила историю прабабушки в музейной исследовательской работе гимназии."}}, {"id": "skorobogatova", "name": "Скоробогатова Любовь Георгиевна", "short_name": "Скоробогатова Любовь Георгиевна", "birth_date": "05 октября 1927 г.", "birth_place": "Смоленская обл., ст. Гусина (жила в Микашевичах)", "deportation_age": "15 лет (1943 г.)", "destination": "Германия (крупный промышленный город, трудовой лагерь военного завода)", "liberation": "1945 г. советскими воинами", "quote": "«В лагере со мной дружили две женщины, Вера и Оля. Они меня защищали и оберегали. Там был военный завод, я крутила детали на станке... Только тягостными чувствами сопровождаются воспоминания: постоянно голодные и холодные, тяжёлый труд, постоянный гнёт».", "avatar": "images/photo_25_skorobogatova_2013.jpg", "photos": [{"src": "images/photo_25_skorobogatova_2013.jpg", "caption": "Фото 25. Скоробогатова Л.Г., 2013 год", "tag": "Подлинный портрет"}, {"src": "images/photo_26_skorobogatov_family_prewar.jpg", "caption": "Фото 26. Семья Скоробогатовых перед войной", "tag": "Довоенный снимок"}], "story": {"family": "Большая дружная семья: отец Георгий Петрович (рабочий кожзавода), мама Дарья Гордеевна, сестра Люда, братья Виталий, Кирилл и брат-близнец Валик.", "war_start": "Отец был призван на фронт, мама эвакуировалась в Казахстан, братья ушли на войну, трое подростков остались одни. Видели гибель детей при авианалетах, зверства карателей над еврейским населением и советскими военнопленными.", "deportation": "В 1943 г. отступающие нацисты подожгли дом, детей затолкнули в грузовик и увезли через Минск и Слоним в Германию. Брата Валика угнали на запад, сестру Люду оставили в Польше, а 15-летнюю Любу отправили в промышленный трудовой лагерь в Германии.", "forced_labor": "Тяжелейший труд у станка на военном заводе, рытье окопов, чистка картофеля, постоянное истощение и страх. От произвола охраняли старшие русские женщины-узницы Вера и Оля.", "liberation": "Освобождена советскими войсками и возвращена на Родину.", "peace_life": "Вернулись братья и мама, солдаты привезли тяжелобольного отца, который вскоре скончался. Любовь окончила семилетку, работала на кирпичном заводе, окончила Новогрудский финансовый техникум. В 1951 г. вышла замуж за Хмельницкого Фёдора Максимовича и переехала в Микашевичи, вырастила сыновей Владимира и Георгия."}}, {"id": "yakubovich", "name": "Якубович Григорий Яковлевич", "short_name": "Якубович Григорий Яковлевич", "birth_date": "07 октября 1923 г.", "birth_place": "д. Кожан-Городок, Лунинецкий р-н, Пинская обл.", "deportation_age": "18 лет (1942 г.)", "destination": "Шнайдемюль (хозяин Дегнер) → Концентрационный лагерь «Заксенхаузен»", "liberation": "1945 г. советскими воинами", "quote": "«Поймали нас в лесу и отвезли в концлагерь „Заксенхаузен“. Работали по 10 часов, на работу водили под конвоем: если шатался — стреляли. На территории размещалось 70 бараков, включая огромные печи, где палили людей... День и ночь шел дым, вонь сильная стояла».", "avatar": "images/photo_27_yakubovich_2013.jpg", "photos": [{"src": "images/photo_27_yakubovich_2013.jpg", "caption": "Фото 27. Якубович Григорий Яковлевич, 2013 год", "tag": "Подлинный портрет"}, {"src": "images/photo_28_yakubovich_cert_1996.jpg", "caption": "Фото 28. Удостоверение узника концлагеря №094105", "tag": "Удостоверение"}], "story": {"family": "Родился в крестьянской семье Якова Петровича и Арины Игнатьевны в Кожан-Городке. В семье росли пятеро сыновей: Тимох, Вася, Гриша, Миша и Вова.", "war_start": "В 1942 г. староста деревни составил списки на принудительный вывоз молодежи в Германию. Парней из Кожан-Городка погрузили в эшелон и доставили в Шнайдемюль.", "deportation": "Работал у бауэра Дегнера на пахоте и уходе за лошадьми. Четверо полешуков затосковали по дому и наивно решили бежать через лес на станцию. Беглецов поймали в лесу и отправили в печально известный концлагерь Заксенхаузен под Берлином.", "forced_labor": "Заксенхаузен: 70 бараков, крематорий с гигантскими печами, непрерывный смрад сжигаемых тел. 10 часов каторги под дулами карателей: цементирование полов, монтаж тяжелых станков. Еда — баланда из ракушек и 150 грамм опилочного хлеба в день. При наступлении советских войск узников погнали маршем смерти, бросив обессилевших в поле.", "liberation": "Освобождены советскими воинами. Служил полтора года в 185-м запасном армейском полку в Жабинке.", "peace_life": "Вернулся на Полесье, работал кочегаром, машинистом и слесарем на лесозаводе в Микашевичах. В 1947 г. женился на швее Галине Герасимовне, вырастили четверых детей (Николай, Владимир, Людмила, Нелли)."}}, {"id": "yasko", "name": "Ясько (Тристень) Лидия Платоновна", "short_name": "Ясько Лидия Платоновна", "birth_date": "11 декабря 1931 г.", "birth_place": "деревня Перуново, Лунинецкий р-н", "deportation_age": "11 лет (1943 г.)", "destination": "Германия (Эрфурт, бауэрское хозяйство)", "liberation": "1945 г. американскими войсками на реке Одер", "quote": "«В 1945 году нас переправили через реку Одер и отдали русским. Свобода, счастье — что может быть лучше? Не было дыма, не воняло людским мясом, никто не стрелял. Счастье было в том, что ты ложился спать и слышал тишину...»", "avatar": "images/photo_29_yasko_2013.jpg", "photos": [{"src": "images/photo_29_yasko_2013.jpg", "caption": "Фото 29. Ясько Л.П., 2013 год", "tag": "Подлинный портрет"}, {"src": "images/photo_30_yasko_cert_2005.jpg", "caption": "Фото 30. Памятного нагрудного знака «Узника нацизма» на имя Ясько Л.П.", "tag": "Нагрудный знак"}], "story": {"family": "Родители Платон и Стефанида очень любили детей: Аню, Веру, Николая, Павла и Лиду. Жили в Перуново. Во время рейдов партизан прятали в сундуке в яме ящик с минами, спасая народных мстителей.", "war_start": "В 1942 г. возили сдавать молоко в д. Любань и слышали пулеметные очереди уничтожения Лахвенского еврейского гетто.", "deportation": "В 1943 г. власовцы сожгли хутора и согнали жителей в Лахву, откуда в запертых товарных вагонах повезли в Германию. В Эрфурте сортировали как скот: право — к хозяевам, лево — в концлагерь.", "forced_labor": "Семью забрал немецкий помещик. Бараки кишели вшами. Дети наравне со взрослыми таскали тяжелые тюки сена, мыли, пекли хлеб, чистили хлева. За пять минут отдыха следовало жестокое наказание.", "liberation": "В 1945 г. освобождены американскими войсками, отказались от вербовки в США и через реку Одер переданы советским войскам.", "peace_life": "В Перуново дом уцелел. Отец мастерил веретена и корыта (начоўкі), ходили продавать в Давид-Городок и Ольшаны. В хлеб добавляли желуди, вереск и шелуху. В 1950 г. вышла замуж, вырастила двух дочерей — Тамару и Светлану."}}];
