// ==========================================================================
// ROUTER & VIEW SWITCHING (Animated transitions)
// ==========================================================================

function navigateTo(hash, addToHistory = true) {
  if (!hash || hash === '' || hash === '#') {
    hash = '#home';
  }
  
  if (addToHistory && window.location.hash !== hash) {
    window.location.hash = hash;
    return;
  }

  const cleanHash = hash.replace(/^#\/?/, '');
  const parts = cleanHash.split('/');
  const route = parts[0] || 'home';
  const param = parts[1] || null;

  // Handle views
  let targetViewId = 'view-home';
  
  if (route === 'history') targetViewId = 'view-history';
  else if (route === 'people') targetViewId = 'view-people';
  else if (route === 'person' && param) {
    targetViewId = 'view-person';
    state.currentPersonId = param;
    renderPersonDetail(param);
  }
  else if (route === 'map') targetViewId = 'view-map';
  else if (route === 'archive') targetViewId = 'view-archive';
  else if (route === 'quiz') targetViewId = 'view-quiz';
  else targetViewId = 'view-home';

  // Animated Switch
  elements.views.forEach(v => {
    if (v.classList.contains('active-view')) {
      v.classList.remove('active-view');
      v.style.display = 'none';
    }
  });

  const targetElem = document.getElementById(targetViewId);
  if (targetElem) {
    targetElem.style.display = 'block';
    // Trigger reflow for animation
    void targetElem.offsetWidth;
    targetElem.classList.add('active-view');
    targetElem.classList.add('fade-in');
  }

  // Update Nav links
  elements.navLinks.forEach(link => {
    const linkHash = link.getAttribute('data-tab');
    if (linkHash === route) {
      link.classList.add('active');
    } else {
      link.classList.remove('active');
    }
  });

  // Close mobile drawer if open
  closeDrawer();

  // Scroll to top
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

// Setup Hash Listener
window.addEventListener('hashchange', () => {
  navigateTo(window.location.hash, false);
});

