// ==========================================================================
// ARCHIVE RENDERING
// ==========================================================================

function renderArchiveGrid(filter = 'all') {
  if (!elements.archiveGrid) return;
  elements.archiveGrid.innerHTML = '';

  let filtered = ARCHIVE_PHOTOS;
  if (filter === 'portrait') {
    filtered = ARCHIVE_PHOTOS.filter(ph => ph.tag.includes('Портрет') || ph.tag.includes('свидетель'));
  } else if (filter === 'doc') {
    filtered = ARCHIVE_PHOTOS.filter(ph => ph.tag.includes('документ') || ph.tag.includes('Справка') || ph.tag.includes('Удостоверение') || ph.tag.includes('Вкладыш'));
  } else if (filter === 'camp') {
    filtered = ARCHIVE_PHOTOS.filter(ph => ph.tag.includes('лагер') || ph.tag.includes('Довоен') || ph.tag.includes('Остарбайтер') || ph.tag.includes('Советская Армия'));
  } else if (filter === 'saley') {
    filtered = ARCHIVE_PHOTOS.filter(ph => ph.person_id === 'saley');
  }

  filtered.forEach((item, index) => {
    const card = document.createElement('div');
    card.className = 'archive-item-card';
    card.onclick = () => openLightboxGlobal(filtered, index);
    card.innerHTML = `
      <div class="archive-img-wrap">
        <img src="${item.src}" alt="${item.caption}" loading="lazy">
      </div>
      <div class="archive-info">
        <span class="archive-tag">${item.tag}</span>
        <div class="archive-caption">${item.caption}</div>
        <div class="archive-person-name">Личность: ${item.person_name}</div>
      </div>
    `;
    elements.archiveGrid.appendChild(card);
  });
}

// ==========================================================================
// LIGHTBOX MODAL
// ==========================================================================

function openLightboxFromPerson(personId, photoIndex) {
  const person = PEOPLE_DATA.find(p => p.id === personId);
  if (!person) return;
  state.lightboxList = person.photos.map(ph => ({
    src: ph.src,
    caption: ph.caption,
    sub: `${person.name} • Документ из архива`
  }));
  state.lightboxIndex = photoIndex;
  showLightbox();
}

function openLightboxGlobal(list, index) {
  state.lightboxList = list.map(item => ({
    src: item.src,
    caption: item.caption,
    sub: `Остарбайтер: ${item.person_name} (${item.tag})`
  }));
  state.lightboxIndex = index;
  showLightbox();
}

function showLightbox() {
  const current = state.lightboxList[state.lightboxIndex];
  if (!current) return;
  elements.lightboxImg.src = current.src;
  elements.lightboxCaption.textContent = current.caption;
  elements.lightboxSub.textContent = current.sub;
  elements.lightbox.classList.add('active');
  document.body.style.overflow = 'hidden';
}

function closeLightbox() {
  elements.lightbox.classList.remove('active');
  document.body.style.overflow = '';
}

function nextLightboxPhoto() {
  if (state.lightboxList.length <= 1) return;
  state.lightboxIndex = (state.lightboxIndex + 1) % state.lightboxList.length;
  showLightbox();
}

function prevLightboxPhoto() {
  if (state.lightboxList.length <= 1) return;
  state.lightboxIndex = (state.lightboxIndex - 1 + state.lightboxList.length) % state.lightboxList.length;
  showLightbox();
}

// Keyboard navigation for lightbox
window.addEventListener('keydown', (e) => {
  if (!elements.lightbox.classList.contains('active')) return;
  if (e.key === 'Escape') closeLightbox();
  if (e.key === 'ArrowRight') nextLightboxPhoto();
  if (e.key === 'ArrowLeft') prevLightboxPhoto();
});

