function openDrawer() {
  elements.mobileDrawer.classList.add('open');
  elements.drawerOverlay.classList.add('active');
}

function closeDrawer() {
  elements.mobileDrawer.classList.remove('open');
  elements.drawerOverlay.classList.remove('active');
}

