function filterPeople() {
  let list = PEOPLE_DATA;
  const filter = state.activeFilter;
  const q = state.searchQuery.toLowerCase().trim();

  if (filter === 'children') {
    list = list.filter(p => parseInt(p.deportation_age) <= 14);
  } else if (filter === 'camp') {
    list = list.filter(p => p.destination.includes('лагерь') || p.destination.includes('Майданек') || p.destination.includes('Заксенхаузен'));
  } else if (filter === 'bauer') {
    list = list.filter(p => p.destination.includes('бауэр') || p.destination.includes('поместье') || p.destination.includes('хозяйство'));
  } else if (filter === 'industry') {
    list = list.filter(p => p.destination.includes('завод') || p.destination.includes('флот') || p.destination.includes('станки') || p.destination.includes('Берлин'));
  }

  if (q) {
    list = list.filter(p => 
      p.name.toLowerCase().includes(q) ||
      p.birth_place.toLowerCase().includes(q) ||
      p.destination.toLowerCase().includes(q) ||
      p.quote.toLowerCase().includes(q)
    );
  }

  renderPeopleCards(list, elements.peopleGrid, false);
}

function resetPeopleFilters() {
  state.activeFilter = 'all';
  state.searchQuery = '';
  if (elements.searchInput) elements.searchInput.value = '';
  document.querySelectorAll('.filter-btn').forEach(btn => {
    if (btn.getAttribute('data-filter') === 'all') btn.classList.add('active');
    else btn.classList.remove('active');
  });
  filterPeople();
}


