const quizState = {
  activeQuestions: [], // 10 randomly picked
  currentIndex: 0,
  userAnswers: [], // stores { question, selectedOption, isCorrect, explanation }
  score: 0,
  isAnswered: false
};

// Fisher-Yates array shuffle helper
function shuffleArray(array) {
  const arr = [...array];
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

// Initialize and start a new 10-question quiz run
function initQuiz() {
  // 1. Shuffle all 30 questions and select exactly 10
  const shuffled30 = shuffleArray(ALL_QUIZ_QUESTIONS);
  const selected10 = shuffled30.slice(0, 10);

  // 2. For each question, shuffle options as well so correct answer position varies
  quizState.activeQuestions = selected10.map(q => {
    const origCorrectText = q.options[q.correct];
    const shuffledOptions = shuffleArray(q.options);
    const newCorrectIdx = shuffledOptions.indexOf(origCorrectText);
    return {
      id: q.id,
      question: q.question,
      options: shuffledOptions,
      correct: newCorrectIdx,
      explanation: q.explanation
    };
  });

  quizState.currentIndex = 0;
  quizState.userAnswers = [];
  quizState.score = 0;
  quizState.isAnswered = false;

  renderQuizCard();
}

// Render current question inside the quiz container
function renderQuizCard() {
  const container = document.getElementById('quizDynamicContent');
  if (!container) return;

  const currentQ = quizState.activeQuestions[quizState.currentIndex];
  if (!currentQ) return;

  const qNum = quizState.currentIndex + 1;
  const totalQ = quizState.activeQuestions.length; // 10
  const progressPercent = (qNum / totalQ) * 100;

  let optionsHtml = '';
  currentQ.options.forEach((optText, optIdx) => {
    optionsHtml += `
      <button class="quiz-option-btn" id="quizOptBtn_${optIdx}" onclick="handleSelectQuizOption(${optIdx})">
        <span><strong>${optIdx + 1}.</strong> ${optText}</span>
        <span class="quiz-opt-icon" id="quizOptIcon_${optIdx}">➜</span>
      </button>
    `;
  });

  container.innerHTML = `
    <div class="quiz-card">
      <div class="quiz-top-info">
        <span class="quiz-counter-tag">Вопрос ${qNum} из ${totalQ}</span>
        <span class="quiz-score-badge">Правильно: <strong id="quizScoreCount">${quizState.score}</strong></span>
      </div>

      <div class="quiz-progress-bar-wrap">
        <div class="quiz-progress-fill" style="width: ${progressPercent}%;"></div>
      </div>

      <h3 class="quiz-question-title">${currentQ.question}</h3>

      <div class="quiz-options">
        ${optionsHtml}
      </div>

      <div class="quiz-feedback-box" id="quizFeedbackBox"></div>

      <div class="quiz-bottom-actions" id="quizBottomActions" style="display: none;">
        <button class="btn btn-primary" onclick="handleNextQuizStep()">
          ${qNum < totalQ ? 'Следующий вопрос →' : 'Посмотреть результаты 🏆'}
        </button>
      </div>
    </div>
  `;
}

// Handle clicking an option
function handleSelectQuizOption(selectedIdx) {
  if (quizState.isAnswered) return;
  quizState.isAnswered = true;

  const currentQ = quizState.activeQuestions[quizState.currentIndex];
  const isCorrect = (selectedIdx === currentQ.correct);

  if (isCorrect) {
    quizState.score++;
    const scoreElem = document.getElementById('quizScoreCount');
    if (scoreElem) scoreElem.textContent = quizState.score;
  }

  // Record answer for final popup review
  quizState.userAnswers.push({
    question: currentQ.question,
    userOption: currentQ.options[selectedIdx],
    correctOption: currentQ.options[currentQ.correct],
    isCorrect: isCorrect,
    explanation: currentQ.explanation
  });

  // Update button styles
  currentQ.options.forEach((_, idx) => {
    const btn = document.getElementById(`quizOptBtn_${idx}`);
    const icon = document.getElementById(`quizOptIcon_${idx}`);
    if (btn) {
      btn.disabled = true;
      if (idx === currentQ.correct) {
        btn.classList.add('selected-correct');
        if (icon) icon.textContent = '✓';
      } else if (idx === selectedIdx) {
        btn.classList.add('selected-wrong');
        if (icon) icon.textContent = '✗';
      }
    }
  });

  // Show feedback explanation
  const feedbackBox = document.getElementById('quizFeedbackBox');
  if (feedbackBox) {
    feedbackBox.className = isCorrect ? 'quiz-feedback-box correct' : 'quiz-feedback-box wrong';
    feedbackBox.innerHTML = `
      <strong>${isCorrect ? '✓ Правильно!' : '✗ Неверно'}</strong>
      ${!isCorrect ? `Правильный ответ: <em>${currentQ.options[currentQ.correct]}</em><br>` : ''}
      ${currentQ.explanation}
    `;
    feedbackBox.style.display = 'block';
  }

  // Reveal next button
  const bottomActions = document.getElementById('quizBottomActions');
  if (bottomActions) {
    bottomActions.style.display = 'flex';
  }
}

// Move to next question or show popup results
function handleNextQuizStep() {
  quizState.currentIndex++;
  quizState.isAnswered = false;

  if (quizState.currentIndex < quizState.activeQuestions.length) {
    renderQuizCard();
  } else {
    // Quiz completed: show modal popup with detailed results!
    showQuizResultsModal();
    renderQuizCompletionOnPage();
  }
}

// Render page summary card when quiz finishes
function renderQuizCompletionOnPage() {
  const container = document.getElementById('quizDynamicContent');
  if (!container) return;

  const total = quizState.activeQuestions.length;
  const score = quizState.score;
  const pct = Math.round((score / total) * 100);

  container.innerHTML = `
    <div class="quiz-card" style="text-align: center; padding: 3rem 2rem;">
      <div style="font-size: 3.5rem; margin-bottom: 1rem;">🏆</div>
      <h3 style="font-size: 1.8rem; margin-bottom: 0.8rem;">Викторина успешно завершена!</h3>
      <p style="font-size: 1.3rem; color: var(--accent-red); font-weight: 800; font-family: var(--font-serif); margin-bottom: 0.5rem;">
        Ваш результат: ${score} из ${total} (${pct}%)
      </p>
      <p style="color: var(--text-secondary); max-width: 550px; margin: 0 auto 1.8rem; font-size: 0.95rem;">
        Вы ответили на 10 случайных вопросов по истории остарбайтерства в Беларуси. Нажмите кнопку ниже, чтобы еще раз взглянуть на подробный разбор ответов или запустить новый тест со следующими 10 вопросами.
      </p>
      <div style="display: flex; justify-content: center; gap: 0.8rem; flex-wrap: wrap;">
        <button class="btn btn-secondary" onclick="showQuizResultsModal()">Показать окно с разбором ответов</button>
        <button class="btn btn-primary" onclick="initQuiz()">Пройти снова (новые 10 вопросов) ↻</button>
      </div>
    </div>
  `;
}

// Open the Modal Popup Window with full breakdown
function showQuizResultsModal() {
  let modalOverlay = document.getElementById('quizResultModalOverlay');
  if (!modalOverlay) {
    // Create modal if not in DOM
    modalOverlay = document.createElement('div');
    modalOverlay.id = 'quizResultModalOverlay';
    modalOverlay.className = 'quiz-modal-overlay';
    document.body.appendChild(modalOverlay);
  }

  const total = quizState.userAnswers.length;
  const score = quizState.score;
  const pct = Math.round((score / total) * 100);

  let comment = '';
  let trophy = '🏆';
  if (score === 10) {
    comment = 'Великолепно! Вы безошибочно ответили на все вопросы и прекрасно знаете исторический материал о трагедии белорусских остарбайтеров.';
    trophy = '🌟';
  } else if (score >= 7) {
    comment = 'Очень хороший результат! Вы уверенно ориентируетесь в исторических фактах и документах времен Великой Отечественной войны.';
    trophy = '🎖️';
  } else if (score >= 4) {
    comment = 'Достойный результат! Все детали и точные цифры можно освежить, прочитав раздел «Об остарбайтерах» на нашем сайте.';
    trophy = '📖';
  } else {
    comment = 'Не расстраивайтесь! Прочтите исторические статьи на нашем сайте и пройдите викторину снова — вопросы будут другими!';
    trophy = '🌱';
  }

  // Build breakdown list
  let breakdownHtml = '';
  quizState.userAnswers.forEach((ans, idx) => {
    const isCorr = ans.isCorrect;
    breakdownHtml += `
      <div class="quiz-review-item ${isCorr ? 'is-correct' : 'is-wrong'}">
        <div class="review-q-num ${isCorr ? 'text-correct' : 'text-wrong'}">
          <span>${isCorr ? '✓ Верно' : '✗ Ошибка'}</span> • Вопрос ${idx + 1} из ${total}
        </div>
        <div class="review-q-text">${ans.question}</div>
        <div class="review-answer-row">
          <span class="review-ans-label">Ваш ответ:</span> 
          <span class="review-ans-val ${isCorr ? 'correct-val' : 'wrong-val'}">${ans.userOption}</span>
        </div>
        ${!isCorr ? `
          <div class="review-answer-row">
            <span class="review-ans-label">Правильный ответ:</span> 
            <span class="review-ans-val correct-val">${ans.correctOption}</span>
          </div>
        ` : ''}
        <div class="review-explanation">
          <strong>Историческая справка:</strong> ${ans.explanation}
        </div>
      </div>
    `;
  });

  modalOverlay.innerHTML = `
    <div class="quiz-modal-card" role="dialog" aria-modal="true">
      <div class="quiz-modal-header">
        <h3>Итоги викторины</h3>
        <button class="quiz-modal-close-btn" onclick="closeQuizResultsModal()" aria-label="Закрыть">✕</button>
      </div>

      <div class="quiz-modal-body">
        <div class="quiz-score-banner">
          <div class="quiz-score-trophy">${trophy}</div>
          <div class="quiz-score-number">${score} из ${total}</div>
          <div class="quiz-score-label">Правильных ответов (${pct}%)</div>
          <p class="quiz-score-comment">${comment}</p>
        </div>

        <h4 class="quiz-breakdown-heading">
          <span>📋</span> Подробный разбор каждого вопроса:
        </h4>

        <div class="quiz-review-list">
          ${breakdownHtml}
        </div>
      </div>

      <div class="quiz-modal-footer">
        <button class="btn btn-secondary" onclick="closeQuizResultsModal()">Закрыть окно</button>
        <button class="btn btn-primary" onclick="closeQuizResultsModal(); initQuiz();">
          Пройти снова (новые 10 вопросов) ↻
        </button>
      </div>
    </div>
  `;

  modalOverlay.classList.add('active');
  document.body.style.overflow = 'hidden';
}

function closeQuizResultsModal() {
  const modalOverlay = document.getElementById('quizResultModalOverlay');
  if (modalOverlay) {
    modalOverlay.classList.remove('active');
  }
  document.body.style.overflow = '';
}


// ==========================================================================
// INITIALIZATION
// ==========================================================================

document.addEventListener('DOMContentLoaded', () => {
  // Initial renders
  renderPeopleCards(PEOPLE_DATA, elements.peopleGrid, false);
  renderPeopleCards(PEOPLE_DATA, elements.homePeopleTeaser, true);
  renderArchiveGrid('all');
  initQuiz();

  // Mobile drawer controls
  if (elements.mobileMenuBtn) elements.mobileMenuBtn.addEventListener('click', openDrawer);
  if (elements.closeDrawerBtn) elements.closeDrawerBtn.addEventListener('click', closeDrawer);
  if (elements.drawerOverlay) elements.drawerOverlay.addEventListener('click', closeDrawer);

  // Search input
  if (elements.searchInput) {
    elements.searchInput.addEventListener('input', (e) => {
      state.searchQuery = e.target.value;
      filterPeople();
    });
  }

  // Filter Buttons for people
  document.querySelectorAll('.filter-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      state.activeFilter = btn.getAttribute('data-filter');
      filterPeople();
    });
  });

  // Archive Filter Tabs
  document.querySelectorAll('.archive-tab-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.archive-tab-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      renderArchiveGrid(btn.getAttribute('data-archive-filter'));
    });
  });

  // Handle Initial Route from URL
  navigateTo(window.location.hash || '#home', false);
});
